<script setup lang="ts">import{computed,shallowRef,watch}from'vue';import{ElMessage}from'element-plus';import{intelligenceApi,type CodeGraphArtifact,type GraphResult}from'@/api/intelligence';import{useRepositoryStore}from'@/stores/repositoryStore';const repos=useRepositoryStore(),depth=shallowRef(3),symbol=shallowRef(''),result=shallowRef<GraphResult|null>(null),artifact=shallowRef<CodeGraphArtifact|null>(null),busy=shallowRef(false),building=shallowRef(false);const positioned=computed(()=>result.value?.nodes.slice(0,40).map((n,i)=>({...n,x:7+(i%4)*23,y:8+Math.floor(i/4)*15}))??[]);async function loadArtifact(){artifact.value=repos.selectedRepositoryId?await intelligenceApi.latestGraph(repos.selectedRepositoryId):null}async function build(){if(!repos.selectedRepositoryId)return ElMessage.warning('请先选择仓库');building.value=true;try{artifact.value=await intelligenceApi.buildGraph(repos.selectedRepositoryId);ElMessage.success('CodeGraph 产物已发布')}catch(e){ElMessage.error(e instanceof Error?e.message:'构建失败')}finally{building.value=false}}async function analyze(){if(!repos.selectedRepositoryId)return ElMessage.warning('请先选择仓库');if(!symbol.value.trim())return ElMessage.warning('请输入符号名');busy.value=true;try{result.value=await intelligenceApi.graph(repos.selectedRepositoryId,symbol.value.trim(),depth.value,'BOTH')}catch(e){ElMessage.error(e instanceof Error?e.message:'分析失败')}finally{busy.value=false}}watch(()=>repos.selectedRepositoryId,()=>void loadArtifact(),{immediate:true});</script>
<template><section class="graph-page"><div class="graph-toolbar"><el-input v-model="symbol" class="graph-search" placeholder="输入类、函数、方法或路由符号"/><label>深度 <el-input-number v-model="depth" :min="1" :max="5" size="small"/></label><el-tag v-if="artifact" type="success">CodeGraph {{artifact.cliVersion}} · {{artifact.status}}</el-tag><el-button :loading="building" @click="build">{{artifact?'重新构建':'构建 CodeGraph'}}</el-button><el-button type="primary" :loading="busy" @click="analyze">影响分析</el-button></div><div class="graph-workspace"><main class="graph-canvas"><el-empty v-if="!positioned.length" description="构建 CodeGraph 后输入符号进行分析"/><button v-for="node in positioned" :key="node.symbol" :class="['graph-card',node.focus?'core':'service']" :style="{left:node.x+'%',top:node.y+'%'}"><small>{{node.focus?'目标符号':'受影响'}}</small><b>{{node.symbol}}</b></button></main><aside class="impact-panel"><div class="pane-head"><b>确定性影响分析</b><span>深度 {{depth}}</span></div><div class="impact-score"><b>{{result?.risk??'—'}}</b><span>变更风险</span></div><h3>影响关系（{{result?.edges.length??0}}）</h3><ul><li v-for="(edge,i) in result?.edges.slice(0,80)" :key="i">{{edge.source}} → {{edge.target}}</li></ul><el-alert v-for="item in result?.limitations" :key="item" :title="item" type="info" :closable="false" style="margin-top:8px"/></aside></div></section></template>
